$_MODULE['<{sudemi}prestashop>sudemi_a473565a143cf3cdb01895753a94ccab'] = 'İade kabul edildi. Alıcıya ürünü geri göndermesi söylenir. Ürün geri geldiğinde bu siparişi her zamanki gibi iade edin (Geri ödendi durumu veya bir kısmı için iade faturası): iade sudemi üzerinden alıcıya gider ve talebi kapatır.';
$_MODULE['<{sudemi}prestashop>sudemi_cb2539cea371b3e5736c3444acbfccf9'] = 'İade reddedildi. sudemi gerekçenizi alıcıya gösterir.';
$_MODULE['<{sudemi}prestashop>sudemi_8af7448f2470dbdf3e3c52b23b771e9d'] = 'Bu iade talebi zaten yanıtlanmıştı (sudemi\'de veya süre dolduktan sonra sudemi tarafından). Hiçbir şey değiştirilmedi.';
